const crypto = require('crypto');
const fs = require('fs');
const path = require('path');
const { PrismaClient } = require('@prisma/client');

const ORG = 'faa710c9-6d91-4079-a7d5-91fdccdec14a';
const VEH = {
  tesla: '68868291-5478-42cd-b0c4-cc77b2a78e21',
  tiguan: '19fedd4b-c4e8-4de8-a125-dab293326e7e',
  audi: 'c10351f8-b6a2-4258-947f-631aeaa6d359',
  arteon: '8c850ff1-4201-432b-af2e-2711dbc7ca48',
};
const ADAPTER = 'tire-ds4-shadow-input-v1.1.1';
const EXPECTED = {
  tesla: 15,
  tiguan: 9,
  audi: 30,
  arteon: 12,
};
const EXPECTED_SHA = '440db67229bbd1f1b9b98b43cb6d4d661979c697';
const backendRoot = process.argv.find((a) => a.startsWith('--backend='))?.slice(10) || '/opt/synqdrive/current/backend';
const activationAfter = process.argv.find((a) => a.startsWith('--after='))?.slice(8);

function loadDist(rel) {
  return require(path.join(backendRoot, 'dist/src', rel));
}

async function redisQueueDepth() {
  const host = process.env.REDIS_HOST;
  const port = process.env.REDIS_PORT || '6379';
  const pw = process.env.REDIS_PASSWORD;
  const db = process.env.REDIS_DB || '0';
  if (!host) return { total: null };
  const { spawnSync } = require('child_process');
  const auth = pw ? ['-a', pw] : [];
  const base = ['redis-cli', '-h', host, '-p', port, '-n', db, ...auth];
  const rc = (cmd, ...args) =>
    spawnSync(base[0], base.slice(1).concat([cmd, ...args]), { encoding: 'utf8' }).stdout.trim();
  let total = 0;
  const detail = {};
  for (const suffix of ['wait', 'delayed', 'active', 'failed', 'prioritized']) {
    const key = `bull:dimo.tire.ds4-shadow:${suffix}`;
    const t = rc('TYPE', key);
    if (t === 'none') {
      detail[suffix] = 0;
      continue;
    }
    const n =
      t === 'zset' ? parseInt(rc('ZCARD', key) || '0', 10) : parseInt(rc('LLEN', key) || '0', 10);
    detail[suffix] = n;
    total += n;
  }
  return { total, detail };
}

async function main() {
  const { parseTireDs4ShadowVehicleAllowlistV1, isVehicleAllowlistedInTireDs4ShadowStateV1 } =
    loadDist('modules/vehicle-intelligence/tires/ds4-shadow/tire-ds4-shadow-vehicle-allowlist.v1');

  const prisma = new PrismaClient();
  const { execSync } = require('child_process');
  const sha = execSync('git rev-parse HEAD', { cwd: backendRoot, encoding: 'utf8' }).trim();

  const report = {
    productionSha: sha,
    expectedSha: EXPECTED_SHA,
    shaMatch: sha === EXPECTED_SHA,
    flags: {
      TIRE_DS4_SHADOW_ENABLED: process.env.TIRE_DS4_SHADOW_ENABLED,
      TIRE_DS4_SHADOW_CATCHUP_ENABLED: process.env.TIRE_DS4_SHADOW_CATCHUP_ENABLED,
      TIRE_DS4_SHADOW_VEHICLE_ALLOWLIST: process.env.TIRE_DS4_SHADOW_VEHICLE_ALLOWLIST,
      TIRE_WEAR_V3_PRIOR_SHADOW_WRITE_ENABLED: process.env.TIRE_WEAR_V3_PRIOR_SHADOW_WRITE_ENABLED,
      TIRE_WEAR_V3_CUSTOMER_READ_ENABLED: process.env.TIRE_WEAR_V3_CUSTOMER_READ_ENABLED,
      TIRE_WEAR_V3_CUSTOMER_READ_AUTHORITATIVE: process.env.TIRE_WEAR_V3_CUSTOMER_READ_AUTHORITATIVE,
    },
    allowlistState: parseTireDs4ShadowVehicleAllowlistV1(process.env.TIRE_DS4_SHADOW_VEHICLE_ALLOWLIST),
    bullDs4Shadow: await redisQueueDepth(),
  };

  for (const [name, id] of Object.entries(VEH)) {
    report[`allowlisted_${name}`] = isVehicleAllowlistedInTireDs4ShadowStateV1(
      report.allowlistState,
      id,
    );
  }

  const hist = await prisma.$queryRaw`
    SELECT vehicle_id, count(*)::int AS c
    FROM tire_ds4_motion_shadow_input_v1
    WHERE adapter_version = ${ADAPTER} AND organization_id = ${ORG}
      AND vehicle_id = ANY(${Object.values(VEH)}::text[])
    GROUP BY vehicle_id`;

  report.historicalByVehicle = {};
  for (const [k, id] of Object.entries(VEH)) {
    const row = hist.find((r) => r.vehicle_id === id);
    report.historicalByVehicle[k] = row?.c ?? 0;
  }
  report.historicalTotal = Object.values(report.historicalByVehicle).reduce((a, b) => a + b, 0);
  report.historical66Verified =
    report.historicalByVehicle.tesla === EXPECTED.tesla &&
    report.historicalByVehicle.tiguan === EXPECTED.tiguan &&
    report.historicalByVehicle.audi === EXPECTED.audi &&
    report.historicalByVehicle.arteon === EXPECTED.arteon;

  report.baselineCounts = {
    adapterV111: await prisma.tireDs4MotionShadowInputV1.count({ where: { adapterVersion: ADAPTER } }),
    v2Snapshots: await prisma.tireHealthSnapshot.count(),
    priorShadow: await prisma.tireWearV3PriorShadowV1.count(),
    ds4RunsOrg: await prisma.diV0MotionCoreShadowRunV1.count({ where: { organizationId: ORG } }),
    ledgerValid: await prisma.tireTripUsageLedger.count({
      where: { invalidatedAt: null, organizationId: ORG },
    }),
  };

  if (activationAfter) {
    const after = new Date(activationAfter);
    const live = await prisma.$queryRaw`
      SELECT l.vehicle_id, l.trip_id, l.id AS ledger_id, l.processed_at,
             m.id AS adapter_id, m.created_at AS adapter_created_at, m.ds4_read_status
      FROM tire_trip_usage_ledger l
      LEFT JOIN tire_ds4_motion_shadow_input_v1 m
        ON m.tire_trip_usage_ledger_id = l.id AND m.adapter_version = ${ADAPTER}
      WHERE l.organization_id = ${ORG}
        AND l.invalidated_at IS NULL
        AND l.vehicle_id = ANY(${Object.values(VEH)}::text[])
        AND l.processed_at >= ${after}
      ORDER BY l.processed_at DESC
      LIMIT 50`;
    report.postActivationTrips = live;
    report.newLiveAdapterRows = await prisma.tireDs4MotionShadowInputV1.count({
      where: {
        adapterVersion: ADAPTER,
        organizationId: ORG,
        createdAt: { gte: after },
      },
    });
  }

  console.log(JSON.stringify(report, null, 2));
  await prisma.$disconnect();
}

main().catch((e) => {
  console.error(JSON.stringify({ error: String(e.message || e) }));
  process.exit(1);
});
